-- /* wallust template - colors-hyprland */

local colors = {}

-- Dynamically load latest colors from wallust-hyprland.conf if generated by wallust
local search_paths = {
  os.getenv("HOME") .. "/.config/hypr/wallust/wallust-hyprland.conf",
  debug.getinfo(1).source:match("@?(.*/)") and (debug.getinfo(1).source:match("@?(.*/)") .. "wallust-hyprland.conf") or nil,
}

for _, path in ipairs(search_paths) do
  if path then
    local f = io.open(path, "r")
    if f then
      for line in f:lines() do
        local k, v = line:match("^%$([%w_]+)%s*=%s*([^#]+)")
        if k and v then
          colors[k] = v:match("^%s*(.-)%s*$")
        end
      end
      f:close()
      break
    end
  end
end

-- Fallback defaults in case conf is not readable
local defaults = {
  background = "rgb(131518)",
  foreground = "rgb(CDE2F3)",
  color0     = "rgb(3A3C40)",
  color1     = "rgb(05101C)",
  color2     = "rgb(0A1824)",
  color3     = "rgb(0F3375)",
  color4     = "rgb(284258)",
  color5     = "rgb(466D8C)",
  color6     = "rgb(5582A7)",
  color7     = "rgb(B0CEE6)",
  color8     = "rgb(7B90A1)",
  color9     = "rgb(071625)",
  color10    = "rgb(0E1F31)",
  color11    = "rgb(14449D)",
  color12    = "rgb(355876)",
  color13    = "rgb(5D91BB)",
  color14    = "rgb(71ADDE)",
  color15    = "rgb(B0CEE6)",
}

for k, v in pairs(defaults) do
  if not colors[k] then
    colors[k] = v
  end
end

return colors
